// Ambil pesan teks + nomor pengirim dari payload Meta Cloud API.
const body = $input.first().json.body || $input.first().json;
const msg = body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg || msg.type !== 'text') return [{ json: { skip: true } }];
return [{ json: { from: msg.from, text: msg.text.body, messageId: msg.id } }];

